div.script:
        // Quotes array
        const quotes = [
          "hi",
          "'evil s3curiy! you will not prevail!' -saige",
          "i got stuck in the circus...",
          "smints are like gold.",
          "welcome to blur v0.1.0, high-performance browsing.",
          "keep your code clean and your tabs organized."
        ];

        // Tabs State
        let tabs = [
          { id: 1, title: "new tab", url: "blur://newtab" }
        ];
        let activeTabId = 1;
        let historyStack = { 1: ["blur://newtab"] };
        let historyIndex = { 1: 0 };

        // Custom Links State
        let customLinks = JSON.parse(localStorage.getItem('blur_custom_links') || '[]');

        // Music Player State
        let playlist = [
          { title: "blur ambient signal", artist: "nest-proxy", src: "" },
          { title: "cyberpunk chill", artist: "synth-lab", src: "" }
        ];
        let currentTrackIndex = 0;
        let audioElem = new Audio();
        let isPlaying = false;

        // Chat State
        let friends = [
          { id: 1, name: "saige", online: true, messages: [{ sender: "saige", text: "evil s3curiy! you will not prevail!" }] },
          { id: 2, name: "proxy-node", online: true, messages: [{ sender: "proxy-node", text: "repository synchronized successfully." }] }
        ];
        let activeFriendId = 1;

        // Initialize App on Load
        window.onload = function() {
          renderTabs();
          loadRandomQuote();
          renderCustomLinks();
          renderPlaylist();
          renderFriends();
          navigateTo("blur://newtab");
        };

        // Quote selector
        function loadRandomQuote() {
          const q = quotes[Math.floor(Math.random() * quotes.length)];
          const elem = document.getElementById("quote-display");
          if (elem) elem.innerText = `"${q}"`;
        }

        // Tab Management
        function renderTabs() {
          const list = document.getElementById("tabs-list");
          list.innerHTML = "";
          tabs.forEach(tab => {
            const isActive = tab.id === activeTabId;
            const tabDiv = document.createElement("div");
            tabDiv.className = `flex items-center gap-2 px-3 py-1.5 rounded-t-xl cursor-pointer transition-all border-t border-x max-w-[180px] min-w-[120px] justify-between group ${
              isActive ? 'bg-[#050806] border-emerald-500/40 text-emerald-200 shadow-sm' : 'bg-[#030704]/60 border-emerald-900/20 text-emerald-400/60 hover:bg-emerald-950/40'
            }`;
            tabDiv.onclick = () => switchTab(tab.id);

            let iconSvg = '';
            if (tab.url.startsWith("blur://")) {
              iconSvg = 'b';
            }

            tabDiv.innerHTML = `


                ${iconSvg}
                ${tab.title}




            `;
            list.appendChild(tabDiv);
          });
        }

        function addNewTrustTab(url = "blur://newtab", title = "new tab") {
          const newId = tabs.length > 0 ? Math.max(...tabs.map(t => t.id)) + 1 : 1;
          tabs.push({ id: newId, title: title, url: url });
          historyStack[newId] = [url];
          historyIndex[newId] = 0;
          switchTab(newId);
        }

        function addNewTab() {
          addNewTrustTab("blur://newtab", "new tab");
        }

        function closeTab(id) {
          if (tabs.length === 1) return; // Keep at least one tab
          const index = tabs.findIndex(t => t.id === id);
          tabs = tabs.filter(t => t.id !== id);
          if (activeTabId === id) {
            activeTabId = tabs[Math.max(0, index - 1)].id;
          }
          renderTabs();
          loadCurrentTabUrl();
        }

        function switchTab(id) {
          activeTabId = id;
          renderTabs();
          loadCurrentTabUrl();
        }

        function getCurrentTab() {
          return tabs.find(t => t.id === activeTabId) || tabs[0];
        }

        // Navigation
        function navigateTo(url) {
          const tab = getCurrentTab();
          tab.url = url;
          if (url.startsWith("blur://")) {
            tab.title = url.replace("blur://", "");
          } else {
            try {
              const u = new URL(url);
              tab.title = u.hostname.replace("www.", "");
            } catch(e) {
              tab.title = url;
            }
          }

          // Push to history
          if (!historyStack[tab.id]) historyStack[tab.id] = [url];
          else {
            historyStack[tab.id] = historyStack[tab.id].slice(0, historyIndex[tab.id] + 1);
            historyStack[tab.id].push(url);
            historyIndex[tab.id] = historyStack[tab.id].length - 1;
          }

          renderTabs();
          loadCurrentTabUrl();
        }

        function loadCurrentTabUrl() {
          const tab = getCurrentTab();
          document.getElementById("url-input").value = tab.url;

          // Hide all views
          document.querySelectorAll('.app-view').forEach(v => v.classList.add('hidden'));
          document.querySelectorAll('.sidebar-btn').forEach(b => b.classList.remove('bg-emerald-950/80', 'text-emerald-300'));

          const targetId = `view-${tab.url}`;
          const viewElem = document.getElementById(targetId);

          if (viewElem) {
            viewElem.classList.remove('hidden');
          } else {
            // External Proxy View
            const extView = document.getElementById("view-external");
            extView.classList.remove('hidden');
            document.getElementById("external-url-label").innerText = tab.url;
            // Load via proxy or direct embedding if allowed
            document.getElementById("external-iframe").src = tab.url;
          }

          // Highlight sidebar button if internal scheme
          const sidebarBtn = document.getElementById(`sidebar-${tab.url}`);
          if (sidebarBtn) {
            sidebarBtn.classList.add('bg-emerald-950/80', 'text-emerald-300');
          }
        }

        function navigateFromBar() {
          let val = document.getElementById("url-input").value.trim();
          if (!val) return;
          if (!val.startsWith("blur://") && !val.startsWith("http://") && !val.startsWith("https://")) {
            if (val.includes(".") && !val.includes(" ")) {
              val = "https://" + val;
            } else {
              val = "https://www.google.com/search?q=" + encodeURIComponent(val);
            }
          }
          navigateTo(val);
        }

        function handleUrlKeydown(e) {
          if (e.key === "Enter") navigateFromBar();
        }

        function handleHubSearch(e) {
          if (e.key === "Enter") {
            const val = e.target.value.trim();
            if (val) navigateTo(val.startsWith("blur://") ? val : "https://www.google.com/search?q=" + encodeURIComponent(val));
          }
        }

        function goBack() {
          const tab = getCurrentTab();
          if (historyIndex[tab.id] > 0) {
            historyIndex[tab.id]--;
            tab.url = historyStack[tab.id][historyIndex[tab.id]];
            renderTabs();
            loadCurrentTabUrl();
          }
        }

        function goForward() {
          const tab = getCurrentTab();
          if (historyIndex[tab.id] < historyStack[tab.id].length - 1) {
            historyIndex[tab.id]++;
            tab.url = historyStack[tab.id][historyIndex[tab.id]];
            renderTabs();
            loadCurrentTabUrl();
          }
        }

        function reloadPage() {
          loadCurrentTabUrl();
        }

        // Custom Links Modal
        function openCustomLinkModal() {
          document.getElementById("custom-link-modal").classList.remove("hidden");
          document.getElementById("custom-link-modal").classList.add("flex");
        }
        function closeCustomLinkModal() {
          document.getElementById("custom-link-modal").classList.remove("flex");
          document.getElementById("custom-link-modal").classList.add("hidden");
        }
        function saveCustomLink() {
          const name = document.getElementById("modal-app-name").value.trim();
          const url = document.getElementById("modal-app-url").value.trim();
          if (name && url) {
            customLinks.push({ name, url });
            localStorage.setItem('blur_custom_links', JSON.stringify(customLinks));
            renderCustomLinks();
            closeCustomLinkModal();
          }
        }
        function renderCustomLinks() {
          const container = document.getElementById("custom-links-container");
          container.innerHTML = "";
          customLinks.forEach((link, idx) => {
            const div = document.createElement("div");
            div.className = "glass hover:bg-emerald-950/40 px-4 py-2.5 rounded-xl flex items-center gap-3 cursor-pointer border border-emerald-900/40 text-xs font-medium text-emerald-300";
            div.onclick = () => navigateTo(link.url);
            div.innerHTML = `⚡${link.name}`;
            container.appendChild(div);
          });
        }

        // Games Implementation
        function loadGame(type) {
          const container = document.getElementById("game-container");
          if (type === 'snake') {
            container.innerHTML = `



snake arcade (use arrow keys / swipe)


score: 0

            `;
            initSnakeGame();
          } else if (type === 'pong') {
            container.innerHTML = `



pong classic (move mouse up/down)


            `;
            initPongGame();
          } else if (type === 'clicker') {
            container.innerHTML = `



0

blur energy generated
                click to generate

            `;
          }
        }

        let clickerCount = 0;
        function incrementClicker() {
          clickerCount++;
          const elem = document.getElementById("clicker-score");
          if (elem) elem.innerText = clickerCount;
        }

        function initSnakeGame() {
          const canvas = document.getElementById("snake-canvas");
          if (!canvas) return;
          const ctx = canvas.getContext("2d");
          let snake = [{x: 10, y: 10}];
          let food = {x: 15, y: 15};
          let dx = 1, dy = 0;
          let score = 0;

          const interval = setInterval(() => {
            const head = {x: snake[0].x + dx, y: snake[0].y + dy};
            if (head.x < 0 || head.x >= 40 || head.y < 0 || head.y >= 30) {
              clearInterval(interval);
              return;
            }
            snake.unshift(head);
            if (head.x === food.x && head.y === food.y) {
              score += 10;
              document.getElementById("snake-score").innerText = score;
              food = {x: Math.floor(Math.random() * 38), y: Math.floor(Math.random() * 28)};
            } else {
              snake.pop();
            }

            ctx.fillStyle = "#020503";
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.fillStyle = "#22c55e";
            snake.forEach(part => ctx.fillRect(part.x * 10, part.y * 10, 9, 9));

            ctx.fillStyle = "#10b981";
            ctx.fillRect(food.x * 10, food.y * 10, 9, 9);
          }, 100);

          window.onkeydown = (e) => {
            if (e.key === "ArrowUp" && dy === 0) { dx = 0; dy = -1; }
            if (e.key === "ArrowDown" && dy === 0) { dx = 0; dy = 1; }
            if (e.key === "ArrowLeft" && dx === 0) { dx = -1; dy = 0; }
            if (e.key === "ArrowRight" && dx === 0) { dx = 1; dy = 0; }
          };
        }

        function initPongGame() {
          const canvas = document.getElementById("pong-canvas");
          if (!canvas) return;
          const ctx = canvas.getContext("2d");
          let ball = {x: 250, y: 150, dx: 3, dy: 2, radius: 8};
          let paddleY = 120;

          canvas.onmousemove = (e) => {
            const rect = canvas.getBoundingClientRect();
            paddleY = e.clientY - rect.top - 30;
          };

          const interval = setInterval(() => {
            ball.x += ball.dx;
            ball.y += ball.dy;

            if (ball.y < 0 || ball.y > canvas.height) ball.dy *= -1;
            if (ball.x > canvas.width) ball.dx *= -1;
            if (ball.x < 20 && ball.y >= paddleY && ball.y <= paddleY + 60) ball.dx *= -1;

            ctx.fillStyle = "#020503";
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.fillStyle = "#22c55e";
            ctx.fillRect(10, paddleY, 10, 60);

            ctx.beginPath();
            ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
            ctx.fillStyle = "#10b981";
            ctx.fill();
            ctx.closePath();
          }, 30);
        }

        // AI Assistant App Logic
        let aiAttachment = null;
        function handleAiPhotoUpload(e) {
          const file = e.target.files[0];
          if (file) {
            const reader = new FileReader();
            reader.onload = (evt) => {
              aiAttachment = evt.target.result;
              document.getElementById("ai-thumb").src = aiAttachment;
              document.getElementById("ai-filename").innerText = file.name;
              document.getElementById("ai-attachment-preview").classList.remove("hidden");
              document.getElementById("ai-attachment-preview").classList.add("flex");
            };
            reader.readAsDataURL(file);
          }
        }
        function removeAiAttachment() {
          aiAttachment = null;
          document.getElementById("ai-attachment-preview").classList.remove("flex");
          document.getElementById("ai-attachment-preview").classList.add("hidden");
        }
        function sendAiMessage() {
          const input = document.getElementById("ai-input");
          const text = input.value.trim();
          if (!text && !aiAttachment) return;

          const msgContainer = document.getElementById("ai-chat-messages");

          // User Bubble
          let userHtml = `


U

`;
          if (aiAttachment) {
            userHtml += ``;
          }
          userHtml += `${text}`;
          msgContainer.innerHTML += userHtml;
          input.value = "";
          removeAiAttachment();
          msgContainer.scrollTop = msgContainer.scrollHeight;

          // AI Simulated Response
          setTimeout(() => {
            let reply = "i have processed your query through the nest-proxy node. everything looks optimal!";
            if (text.toLowerCase().includes("code")) reply = "blur-learning repository is fully updated with high-performance standards.";
            msgContainer.innerHTML += `



AI

${reply}

            `;
            msgContainer.scrollTop = msgContainer.scrollHeight;
          }, 800);
        }
        function handleAiKeydown(e) { if (e.key === "Enter") sendAiMessage(); }
        function clearAiChat() {
          document.getElementById("ai-chat-messages").innerHTML = `



AI

chat cleared. how can I help you?

          `;
        }

        // Music Player App Logic
        function handleMusicUpload(e) {
          const files = e.target.files;
          for (let file of files) {
            playlist.push({
              title: file.name.replace(/\.[^/.]+$/, ""),
              artist: "local upload",
              src: URL.createObjectURL(file)
            });
          }
          renderPlaylist();
          if (!audioElem.src && playlist.length > 0) loadTrack(0);
        }
        function renderPlaylist() {
          const container = document.getElementById("playlist-container");
          container.innerHTML = "";
          playlist.forEach((track, idx) => {
            const div = document.createElement("div");
            div.className = `p-3 rounded-xl flex items-center justify-between cursor-pointer transition-all border ${
              idx === currentTrackIndex ? 'bg-emerald-950/60 border-emerald-500/50 text-emerald-200' : 'bg-[#030704]/40 border-emerald-900/30 text-emerald-400/70 hover:bg-emerald-950/30'
            }`;
            div.onclick = () => loadTrack(idx);
            div.innerHTML = `


                ${track.title}
                ${track.artist}

              #0${idx+1}
            `;
            container.appendChild(div);
          });
        }
        function loadTrack(index) {
          currentTrackIndex = index;
          const track = playlist[index];
          document.getElementById("current-track-title").innerText = track.title;
          document.getElementById("current-track-artist").innerText = track.artist;
          if (track.src) {
            audioElem.src = track.src;
            audioElem.play();
            isPlaying = true;
            document.getElementById("play-pause-btn").innerHTML = '';
          }
          renderPlaylist();
        }
        function togglePlayPause() {
          if (!audioElem.src && playlist.length > 0) {
            loadTrack(0);
            return;
          }
          if (isPlaying) {
            audioElem.pause();
            isPlaying = false;
            document.getElementById("play-pause-btn").innerHTML = '';
          } else {
            audioElem.play();
            isPlaying = true;
            document.getElementById("play-pause-btn").innerHTML = '';
          }
        }
        function nextTrack() {
          currentTrackIndex = (currentTrackIndex + 1) % playlist.length;
          loadTrack(currentTrackIndex);
        }
        function prevTrack() {
          currentTrackIndex = (currentTrackIndex - 1 + playlist.length) % playlist.length;
          loadTrack(currentTrackIndex);
        }
        audioElem.ontimeupdate = () => {
          if (audioElem.duration) {
            const progress = (audioElem.currentTime / audioElem.duration) * 100;
            document.getElementById("track-progress").value = progress;
            const mins = Math.floor(audioElem.currentTime / 60);
            const secs = Math.floor(audioElem.currentTime % 60);
            document.getElementById("current-time").innerText = `${mins}:${secs < 10 ? '0' : ''}${secs}`;
            const totMins = Math.floor(audioElem.duration / 60);
            const totSecs = Math.floor(audioElem.duration % 60);
            document.getElementById("total-duration").innerText = `${totMins}:${totSecs < 10 ? '0' : ''}${totSecs}`;
          }
        };
        function seekAudio(e) {
          if (audioElem.duration) {
            audioElem.currentTime = (e.target.value / 100) * audioElem.duration;
          }
        }

        // Chat App Logic
        function renderFriends() {
          const list = document.getElementById("friends-list");
          list.innerHTML = "";
          friends.forEach(f => {
            const div = document.createElement("div");
            div.className = `p-3 rounded-xl flex items-center justify-between cursor-pointer transition-all border ${
              f.id === activeFriendId ? 'bg-emerald-950/60 border-emerald-500/50 text-emerald-200' : 'bg-[#030704]/40 border-emerald-900/30 text-emerald-400/70 hover:bg-emerald-950/30'
            }`;
            div.onclick = () => selectFriend(f.id);
            div.innerHTML = `
              ${f.name}

            `;
            list.appendChild(div);
          });
        }
        function selectFriend(id) {
          activeFriendId = id;
          const f = friends.find(item => item.id === id);
          document.getElementById("active-chat-name").innerText = f.name;
          renderMessages();
          renderFriends();
        }
        function renderMessages() {
          const container = document.getElementById("friend-messages");
          const f = friends.find(item => item.id === activeFriendId);
          container.innerHTML = "";
          f.messages.forEach(m => {
            const isMe = m.sender === "me";
            container.innerHTML += `



${isMe ? 'U' : f.name[0]}

${m.text}

            `;
          });
          container.scrollTop = container.scrollHeight;
        }
        function sendChatMessage() {
          const input = document.getElementById("chat-input");
          const text = input.value.trim();
          if (!text) return;
          const f = friends.find(item => item.id === activeFriendId);
          f.messages.push({ sender: "me", text });
          input.value = "";
          renderMessages();

          setTimeout(() => {
            f.messages.push({ sender: f.name, text: "received your message through the blur proxy network." });
            renderMessages();
          }, 1000);
        }
        function handleChatKeydown(e) { if (e.key === "Enter") sendChatMessage(); }

        // Settings Theme Switcher
        function setTheme(theme) {
          // Visual feedback on selected theme
          console.log("theme set to:", theme);
        }
